repo.harvests.py:
"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('lower', 31), ('upper', 19), ('upper', 44), ('lower', 23), ('lower', 9)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)

repo.naming.py:
"""Labels for harvests."""


def label_harvests(names, harvests):
    """Return (lookup, lines): a name -> kilos dict and one 'name: kilos' line per harvest."""
    pairs = zip(names, (x.kilos for x in harvests))
    lookup = dict(pairs)
    lines = ["%s: %s" % (name, value) for name, value in pairs]
    return lookup, lines


def name_list(names):
    """Return the names joined by commas."""
    return ", ".join(names)
